INSERT INTO sheet_places VALUES
  ('Ben Thanh Market (Chợ Bến Thành)', 'CheckIn', 'Chợ Bến Thành, Lê Lai, Bến Thành, Hồ Chí Minh, Việt Nam', 10.772523377088744, 106.69801677307706, 0, 0, 'Chợ lâu đời, đông vui và nhộn nhịp, nhiều sạp đồ lưu niệm và quầy ăn vặt. Hợp với nhóm bạn hoặc khách lần đầu tới Sài Gòn muốn dạo chơi, mua quà. Buổi trưa khá nóng và đông, đi buổi sáng dễ chịu hơn.', ARRAY['Check-in', 'Văn hóa']),
  ('Bột chiên Cô Mẽ', 'Food', '10 Phan Bội Châu, Bến Thành, Hồ Chí Minh, Việt Nam', 10.772640321820708, 106.69876680880392, 50000, 100000, 'Quán bột chiên vỉa hè nức tiếng với đĩa bánh giòn rụm và nước tương pha vừa vị. Rất thích hợp cho bữa xế chiều ăn vặt nhẹ bụng cùng bạn bè. Quán ngồi bàn nhựa lề đường, giờ tan tầm khá đông khách.', ARRAY['Ẩm thực']),
  ('Bánh Bèo Chợ Bến Thành', 'Food', 'Phan Chu Trinh, Bến Thành, Hồ Chí Minh 700900, Việt Nam', 10.772679148727928, 106.69758397948966, 35000, 100000, 'Quầy bánh bèo Huế gia truyền nổi tiếng với đĩa thập cẩm tôm cháy đậm đà. Điểm dừng chân ăn vặt hấp dẫn cho du khách thích ẩm thực miền Trung. Quầy nằm trong chợ, nên ghé sớm để tránh giờ trưa đông đúc.', ARRAY['Ẩm thực']),
  ('Cơm tấm 182', 'Food', '182 Lê Thánh Tôn, Bến Thành, Hồ Chí Minh, Việt Nam', 10.773060663118699, 106.69721951752089, 50000, 80000, 'Quán cơm tấm bình dân quen thuộc với miếng sườn nướng than thơm lừng đậm vị. Phù hợp nạp nhanh năng lượng cho bữa trưa văn phòng và khách tham quan. Giờ trưa quán thường chật kín, nên tranh thủ ghé sớm.', ARRAY['Ẩm thực']),
  ('Local Saigon Cafe - Bến Thành', 'Cafe', '12 Thủ Khoa Huân, Bến Thành, Hồ Chí Minh, Việt Nam', 10.77360393803878, 106.69759051507197, 45000, 80000, 'Quán cà phê phong cách hoài cổ với ban công ngắm nhìn trọn nhịp sống phố thị. Thích hợp trò chuyện nhẹ nhàng, đọc sách hoặc chụp ảnh phong cách vintage. Buổi chiều mát mẻ ngồi ban công đón gió rất thư giãn.', ARRAY['Cà phê', 'Chụp ảnh', 'Chill nhẹ']),
  ('Soo Kafe Bến Thành', 'Cafe', '35 Phan Chu Trinh, Bến Thành, Hồ Chí Minh 70000, Việt Nam', 10.772487045577504, 106.6972203278567, 60000, 95000, 'Quán cà phê tối giản nhiều mảng xanh, sở hữu ban công ngắm phố cực chill. Điểm hẹn lý tưởng để chụp ảnh check-in, hẹn hò hoặc làm việc yên tĩnh. Nên ghé buổi sáng để đón ánh sáng tự nhiên đẹp nhất.', ARRAY['Cà phê', 'Chụp ảnh', 'Chill nhẹ']),
  ('Bảo tàng Mỹ thuật Thành phố Hồ Chí Minh', 'Culture', '97 Phó Đức Chính, Bến Thành, Hồ Chí Minh, Việt Nam', 10.770126366811432, 106.69923765403524, 30000, 30000, 'Tòa dinh thự cổ thời Pháp lộng lẫy, lưu giữ nhiều tác phẩm nghệ thuật giá trị. Điểm đến văn hóa đặc sắc cho người yêu hội họa và thích chụp ảnh nghệ thuật. Bạn nên dành khoảng 1-2 tiếng để thong thả tham quan.', ARRAY['Văn hóa', 'Chụp ảnh']),
  ('Maison Marou Café Ben Thanh', 'Cafe', '144Bis Lê Thánh Tôn, Bến Thành, Hồ Chí Minh, Việt Nam', 10.773871139884477, 106.69797422519976, 60000, 140000, 'Không gian sô-cô-la thủ công cao cấp với nhiều món bánh tráng miệng tinh tế. Hợp cho buổi hẹn hò ngọt ngào, gặp gỡ bạn bè hoặc mua sô-cô-la làm quà. Mức giá tương đối cao nhưng chất lượng bánh nước rất tương xứng.', ARRAY['Cà phê']),
  ('Nhà hát Thành phố Hồ Chí Minh', 'CheckIn', '07 Công trường Lam Sơn, Sài Gòn, Hồ Chí Minh 700000, Việt Nam', 10.776791935454133, 106.70315001856433, 80000, 1750000, 'Công trình kiến trúc Pháp cổ kính tráng lệ, biểu tượng văn hóa lâu đời của Sài Gòn. Thích hợp dừng chân check-in ngoại cảnh hoặc thưởng thức các đêm nhạc kịch đỉnh cao. Buổi tối tòa nhà lên đèn lung linh, khu bậc thềm rất mát.', ARRAY['Check-in', 'Văn hóa', 'Chụp ảnh']),
  ('Café Carré', 'Cafe', '116 Nguyễn Huệ, Sài Gòn, Hồ Chí Minh, Việt Nam', 10.775983387586832, 106.70205785218668, 95000, 3850000, 'Quán cà phê sang trọng phong cách cổ điển, nằm ngay trục đường Nguyễn Huệ sầm uất. Không gian tĩnh lặng, tinh tế, thích hợp tiếp khách hoặc trò chuyện sâu lắng. Giá thành nhỉnh hơn mặt bằng chung, đổi lại dịch vụ rất chu đáo.', ARRAY['Cà phê', 'Chill nhẹ']),
  ('Các xe quán ăn vặt nhỏ xung quanh', 'Food', '07 Công trường Lam Sơn, Sài Gòn, Hồ Chí Minh 700000, Việt Nam', 10.776791935454133, 106.70315001856433, 40000, 100000, 'Dãy xe đẩy ăn vặt bình dân với bánh tráng nướng, cá viên chiên và trà tắc thơm ngon. Điểm tụ tập ưa thích của học sinh, sinh viên ngồi hóng mát buổi tối. Bạn nên hỏi giá trước khi mua và nhớ bỏ rác đúng nơi quy định.', ARRAY['Ẩm thực']),
  ('Phố đi bộ Nguyễn Huệ', 'CheckIn', 'Nguyễn Huệ, Sài Gòn, Hồ Chí Minh, Việt Nam', 10.774231202620333, 106.70361783102214, 0, 0, 'Quảng trường đi bộ sôi động bậc nhất trung tâm với nhiều hoạt động biểu diễn đường phố. Nơi lý tưởng để dạo mát buổi tối, chụp ảnh và cảm nhận nhịp sống hiện đại. Cuối tuần thường rất đông đúc, bạn nên chú ý bảo quản tư trang.', ARRAY['Check-in', 'Chụp ảnh']),
  ('Dinh Độc Lập', 'CheckIn', 'Bến Thành, Hồ Chí Minh, Việt Nam', 10.777326186754909, 106.69545230006167, 40000, 60000, 'Di tích lịch sử nổi tiếng với kiến trúc thập niên 60 và bãi cỏ xanh mướt rộng lớn. Phù hợp cho du khách khám phá lịch sử, ngắm cảnh và chụp ảnh lưu niệm. Nên dành thời gian tham quan cả khu hầm chỉ huy độc đáo bên dưới.', ARRAY['Văn hóa', 'Check-in', 'Chụp ảnh']),
  ('Nhà thờ Đức Bà Sài Gòn', 'Culture', '01 Công trường Công xã Paris, Quận 1, Hồ Chí Minh 70000, Việt Nam', 10.779839542763987, 106.69900850147589, 0, 0, 'Công trình kiến trúc Gothic bằng gạch đỏ trứ danh, biểu tượng thân thuộc của thành phố. Điểm tham quan không thể bỏ qua để chụp ảnh kỷ niệm và ngắm kiến trúc cổ. Hiện nhà thờ đang trùng tu, du khách chủ yếu chiêm ngưỡng bên ngoài.', ARRAY['Văn hóa', 'Check-in', 'Chụp ảnh']),
  ('Bưu Điện Thành Phố Hồ Chí Minh', 'Culture', '80 Nguyễn Du, Sài Gòn, Hồ Chí Minh, Việt Nam', 10.779933208070622, 106.70068753177883, 0, 0, 'Tòa bưu điện cổ nổi bật với sắc vàng Pháp, mái vòm rộng và buồng điện thoại gỗ xưa. Điểm check-in hoài cổ lý tưởng, nơi bạn có thể gửi bưu thiếp gửi tặng bạn bè. Buổi sáng ánh nắng rọi vào cửa kính mái vòm lên hình rất đẹp.', ARRAY['Văn hóa', 'Check-in', 'Chụp ảnh']),
  ('Thảo Cầm Viên Sài Gòn', 'CheckIn', '2 Nguyễn Bỉnh Khiêm, Sài Gòn, Hồ Chí Minh 700000, Việt Nam', 10.78737508486471, 106.7052351633667, 60000, 60000, 'Vườn thú lâu đời xanh mát giữa lòng phố thị với hệ sinh thái động thực vật đa dạng. Thích hợp cho gia đình có trẻ nhỏ, nhóm bạn picnic hoặc chụp ảnh cổ điển. Nên đi vào sáng sớm mát mẻ để thấy các loài thú hoạt động nhiều.', ARRAY['Check-in', 'Thiên nhiên', 'Chill nhẹ', 'Chụp ảnh']),
  ('Bảo tàng Lịch sử Thành phố Hồ Chí Minh', 'Culture', '2 Nguyễn Bỉnh Khiêm, Sài Gòn, Hồ Chí Minh, Việt Nam', 10.788095344260112, 106.70480248138404, 30000, 30000, 'Nơi trưng bày hàng ngàn cổ vật quý, tái hiện dòng chảy lịch sử văn hóa dân tộc. Điểm đến bổ ích cho các bạn trẻ và du khách yêu thích tìm hiểu lịch sử. Nằm sát Thảo Cầm Viên nên rất tiện kết hợp tham quan trong cùng buổi.', ARRAY['Văn hóa']),
  ('Công viên gầm cầu Ba Son', 'CheckIn', 'Dưới gầm cầu Ba Son (Cầu Thủ Thiêm 2)', 10.780936513433051, 106.70826268930733, 0, 0, 'Khuôn viên bờ sông thoáng đãng với góc ngắm nhìn toàn cảnh Landmark 81 cực đẹp. Điểm tụ tập hóng gió đêm quen thuộc của giới trẻ sau giờ học, giờ làm. Nên ghé lúc hoàng hôn buông xuống để chụp được những bức hình ngược sáng.', ARRAY['Check-in', 'Thiên nhiên', 'Chill nhẹ', 'Chụp ảnh']),
  ('Đường sách Thành phố Hồ Chí Minh', 'CheckIn', '2 Đ. Nguyễn Văn Bình, Sài Gòn, Hồ Chí Minh 700000, Việt Nam', 10.780998945797315, 106.7001283133563, 0, 0, 'Không gian rợp bóng cây mát rượi với nhiều gian hàng sách và quán cà phê thanh lịch. Nơi lý tưởng để tản bộ, chọn mua những cuốn sách hay và thư giãn tâm hồn. Cuối tuần ở đây thường có nhiều triển lãm tranh ảnh và giao lưu tác giả.', ARRAY['Văn hóa', 'Check-in', 'Chill nhẹ']),
  ('Công viên Tao Đàn', 'CheckIn', 'Bến Thành, Hồ Chí Minh 700000, Việt Nam', 10.775618478466736, 106.69219380048305, 0, 0, 'Lá phổi xanh yên bình với hàng cây cổ thụ cao rợp bóng và đường đi bộ râm mát. Phù hợp tập thể dục buổi sáng, tản bộ ngắm cảnh hoặc ngồi đọc sách thư giãn. Sáng sớm ở góc công viên thường có hội chim hót tụ họp rất vui tai.', ARRAY['Thiên nhiên', 'Chill nhẹ']),
  ('Phố đi bộ Bùi Viện', 'Culture', 'Bùi Viện Phạm Ngũ Lão, phường, Bến Thành, Hồ Chí Minh, Việt Nam', 10.767364213700336, 106.69391915407235, 0, 0, 'Con phố Tây náo nhiệt thâu đêm với âm nhạc sôi động và các quán bia lề đường. Điểm đến hấp dẫn cho ai muốn hòa mình vào không khí giải trí đêm đa văn hóa. Phố đông đúc nhất từ 20h trở đi, bạn chú ý cẩn thận tài sản cá nhân.', ARRAY['Check-in', 'Văn hóa']),
  ('Công viên 23/9', 'CheckIn', 'Bến Thành, Hồ Chí Minh, Việt Nam', 10.768746624345932, 106.69232948366087, 0, 0, 'Khoảng không gian xanh rộng lớn trải dài, kết nối chợ Bến Thành và khu phố Tây. Nơi tụ họp quen thuộc của sinh viên giao lưu tiếng Anh, tập nhảy và dạo mát. Buổi chiều tối không khí thoáng đãng, thích hợp ngồi ghế đá trò chuyện.', ARRAY['Thiên nhiên', 'Chill nhẹ']),
  ('Saigon Centre', 'CheckIn', '65 - 67 Lê Lợi, Sài Gòn, Hồ Chí Minh 71016, Việt Nam', 10.773302253369023, 106.70106817677213, 0, 0, 'Trung tâm thương mại hiện đại quy tụ nhiều thương hiệu quốc tế và khu Takashimaya sầm uất. Điểm đến tuyệt vời để mua sắm, check-in sang chảnh và tránh nóng ngày hè. Khu ẩm thực dưới tầng hầm có rất nhiều món ngon châu Á để lựa chọn.', ARRAY['Check-in', 'Ẩm thực']),
  ('Lacàph Coffee', 'Cafe', '151 Đồng Khởi, Sài Gòn, Hồ Chí Minh, Vietnam', 10.775775683623209, 106.70317159425964, 50000, 100000, 'Không gian cà phê đương đại tôn vinh hạt nông sản Việt qua các công thức sáng tạo. Rất hợp cho người sành cà phê, khách bàn công việc hoặc trải nghiệm văn hóa mới. Bạn nên thử các món pha từ hạt Robusta lên men mang hương vị rất riêng.', ARRAY['Cà phê']),
  ('Tonkin Specialty Coffee', 'Cafe', '91 Lý Tự Trọng, Bến Thành, Hồ Chí Minh 700000, Việt Nam', 10.774481168207808, 106.69833031734396, 49000, 89000, 'Quán cà phê phong cách Indochine ấm cúng với nền nhạc jazz nhẹ nhàng và nội thất gỗ mộc. Lựa chọn tuyệt vời để tìm góc yên tĩnh đọc sách, làm việc hoặc chuyện trò. Đừng quên nếm thử món cà phê trứng béo thơm đặc trưng của quán.', ARRAY['Cà phê', 'Chill nhẹ']),
  ('Bếp Mẹ Ỉn', 'Food', '136/9 Lê Thánh Tôn, Bến Thành, Hồ Chí Minh, Việt Nam', 10.773915434721802, 106.69812427506189, 89000, 279000, 'Quán ăn ấm cúng trong ngõ nhỏ, chuyên phục vụ mâm cơm nhà và món ăn dân dã Việt Nam. Phù hợp cho bữa ăn gia đình ấm cúng hoặc dẫn bạn bè nước ngoài trải nghiệm. Món bánh xèo tôm nhảy và cơm chiên trái dừa là hai món rất nên thử.', ARRAY['Ẩm thực']),
  ('Pizza 4P''s Estella Place', 'Food', 'TTTM Estella Place, 88 Song Hành, Bình Trưng, Hồ Chí Minh 70000, Vietnam', 10.80186300379303, 106.74843830721336, 200000, 800000, 'Nhà hàng ẩm thực Ý phong cách Nhật nổi tiếng với pizza nướng củi và phô mai tự làm. Không gian lịch sự, ấm cúng, rất thích hợp cho tiệc gia đình hoặc hẹn hò. Quán thường kín bàn vào cuối tuần nên bạn hãy nhớ đặt trước qua mạng.', ARRAY['Ẩm thực']),
  ('Bến Bạch Đằng', 'CheckIn', '2 Tôn Đức Thắng, Sài Gòn, Hồ Chí Minh, Việt Nam', 10.77601580483109, 106.7072074693158, 15000, 30000, 'Bến tàu công viên ven sông thoáng đãng, nơi đón các chuyến tàu buýt đường sông Waterbus. Rất hợp để đi dạo hóng gió, ngắm hoàng hôn lãng mạn trên mặt sông Sài Gòn. Nên trải nghiệm đi một chuyến buýt sông chiều muộn ngắm phố lên đèn.', ARRAY['Check-in', 'Thiên nhiên', 'Chill nhẹ', 'Chụp ảnh']),
  ('CieL Dining', 'Food', '6/3, Đ. Số 50, An Khánh, Hồ Chí Minh, Vietnam', 10.804825691780145, 106.73341418323754, 1000000, 5000000, 'Nhà hàng ẩm thực fine dining nổi bật với thực đơn tasting kết hợp kỹ thuật Pháp tinh tế. Điểm hẹn đẳng cấp cho những dịp kỷ niệm quan trọng, tiệc hẹn hò lãng mạn. Trải nghiệm dịch vụ chuyên nghiệp cùng các món ăn biến tấu theo mùa.', ARRAY['Ẩm thực']),
  ('Landmark 81', 'CheckIn', '720A Điện Biên Phủ, Phường, Thạnh Mỹ Tây, Hồ Chí Minh 72300, Vietnam', 10.795173174000526, 106.72207929179483, 0, 0, 'Tòa tháp cao nhất Việt Nam biểu trưng cho bó tre, tích hợp đài quan sát SkyView và TTTM. Điểm đến lý tưởng để ngắm toàn cảnh Sài Gòn từ trên cao, mua sắm và vui chơi. Bạn có thể kết hợp dạo mát tại công viên bờ sông rộng lớn ngay bên cạnh.', ARRAY['Check-in', 'Chụp ảnh']),
  ('Ănăn Saigon', 'Food', 'QPC3+M6Q, 89 Tôn Thất Đạm, Sài Gòn, Hồ Chí Minh 000000, Việt Nam', 10.77183609409217, 106.7031134002095, 1200000, 3800000, 'Nhà hàng đạt sao Michelin, biến tấu món ăn đường phố Việt Nam thành ẩm thực cao cấp. Trải nghiệm độc đáo cho tín đồ ẩm thực muốn khám phá hương vị Việt sáng tạo. Bạn cần đặt bàn trước khá sớm và chuẩn bị ngân sách cho bữa ăn sang trọng.', ARRAY['Ẩm thực']),
  ('Bảo tàng Tôn Đức Thắng', 'Culture', '5 Tôn Đức Thắng, Sài Gòn, Hồ Chí Minh, Việt Nam', 10.777349572997364, 106.70663429461476, 0, 0, 'Không gian lưu giữ trang trọng các hiện vật, hình ảnh về cuộc đời Bác Tôn bên bờ sông Son. Điểm đến giàu ý nghĩa cho du khách muốn tìm hiểu lịch sử đấu tranh cách mạng. Vị trí nằm ngay sát ga Ba Son, thuận tiện kết hợp đi dạo công viên bến tàu.', ARRAY['Văn hóa']),
  ('Cà phê Bệt Nhà Thờ Đức Bà', 'Cafe', '1 Công trường Công xã Paris, Sài Gòn, Hồ Chí Minh, Việt Nam', 10.779023966391753, 106.69922208702619, 30000, 100000, 'Nét văn hóa vỉa hè đặc trưng của giới trẻ Sài Gòn chỉ với vài tờ báo và ly trà sữa, cà phê. Không gian mộc mạc, thoáng mát, thích hợp ngồi ngắm đường phố và trò chuyện rôm rả. Buổi sáng cuối tuần là thời điểm thư thái nhất để ghé trải nghiệm.', ARRAY['Cà phê', 'Chill nhẹ']),
  ('Bảo tàng Chứng tích Chiến tranh', 'Culture', 'Phường 6, Quận 3, Hồ Chí Minh 700000, Việt Nam', 10.779573847891548, 106.69216133457428, 20000, 300000, 'Bảo tàng lịch sử lưu giữ tư liệu, hiện vật chân thực về hậu quả của chiến tranh tại Việt Nam. Điểm tham quan sâu sắc thu hút nhiều du khách trong và ngoài nước chiêm nghiệm. Không gian mang tính lịch sử lắng đọng, bạn nên dành ít nhất 1 giờ tham quan.', ARRAY['Văn hóa']),
  ('Vinhome Golden River Bason', 'CheckIn', 'Aqua 3, 2 Tôn Đức Thắng, Sài Gòn, Hồ Chí Minh, Việt Nam', 10.78695647647344, 106.71128607082215, 0, 0, 'Khu đô thị sinh thái hiện đại sở hữu đường dạo bộ ven sông thoáng mát và bến du thuyền. Nơi lý tưởng để chạy bộ thể dục, hóng gió sông và chụp ảnh phong cách hiện đại. Khuôn viên nội khu sạch đẹp, buổi tối ánh đèn phản chiếu mặt sông rất thơ mộng.', ARRAY['Check-in', 'Thiên nhiên', 'Chill nhẹ', 'Chụp ảnh']),
  ('Pearl Center - Thảo Điền Pearl', 'CheckIn', '12 Quốc Hương, An Khánh, Hồ Chí Minh 700900, Việt Nam', 10.801331692690267, 106.73302042510808, 0, 0, 'Trung tâm thương mại tích hợp rạp chiếu phim, siêu thị và nhiều nhà hàng tiện lợi. Phục vụ nhu cầu giải trí, ăn uống nhanh chóng cho cư dân và du khách khu Thảo Điền. Vị trí kết nối thẳng cụm ga metro, rất tiện dừng chân nghỉ ngơi giữa hành trình.', ARRAY['Check-in', 'Ẩm thực']),
  ('Khu du lịch Tân Cảng', 'Food', 'A100 Đ. Ung Văn Khiêm, Thạnh Mỹ Tây, Hồ Chí Minh, Việt Nam', 10.800055627369263, 106.7252298827678, 60000, 350000, 'Khu ẩm thực nghỉ dưỡng ven sông rợp bóng cây với các nhà hàng bờ sông thoáng đãng. Rất thích hợp cho các buổi liên hoan gia đình, họp lớp hoặc tiệc công ty. Bạn có thể vừa thưởng thức món ngon vừa đón gió sông Sài Gòn mát rượi.', ARRAY['Ẩm thực', 'Thiên nhiên', 'Chill nhẹ']),
  ('Tam Sơn Yachting (Bến Du Thuyền Vinhomes Central)', 'CheckIn', '208 Nguyễn Hữu Cảnh, Thạnh Mỹ Tây, Hồ Chí Minh, Việt Nam', 10.795698177098133, 106.72530312383135, 0, 0, 'Bến du thuyền sang trọng chuẩn quốc tế bên bờ sông với góc chụp ảnh thời thượng. Điểm check-in đẳng cấp mang phong cách hiện đại cho du khách và giới trẻ. Nằm sát mép công viên bờ sông, ngắm hoàng hôn buông xuống đây cực kỳ thơ mộng.', ARRAY['Check-in', 'Chụp ảnh']),
  ('IDOL Quán', 'Food', '25/6A Đ. số 17, Thủ Đức, Hồ Chí Minh, Việt Nam', 10.860470460998565, 106.78738697956219, 49000, 119000, 'Quán lẩu nướng bình dân sôi động với thực đơn món ăn đa dạng và bia giải khát. Điểm tụ họp lý tưởng sau giờ học, giờ làm cho sinh viên và nhóm bạn bè. Giá cả sinh viên rất phải chăng, quán đông vui nhất vào các tối cuối tuần.', ARRAY['Ẩm thực']),
  ('Tô Tượng Thủ Đức - Tiệm Nhà Moon', 'CheckIn', '66 Đ. số 17, Linh Xuân, Hồ Chí Minh 700000, Việt Nam', 10.861019991285202, 106.78793894746148, 20000, 90000, 'Không gian xưởng tô tượng sáng tạo với hàng trăm mẫu tượng thạch cao độc đáo. Nơi thư giãn nhẹ nhàng, phù hợp cho các cặp đôi hẹn hò hoặc nhóm bạn xả stress. Tiệm chuẩn bị sẵn đầy đủ màu vẽ, bạn chỉ cần thỏa sức sáng tạo tác phẩm.', ARRAY['Check-in', 'Chill nhẹ']),
  ('Bò Né Chibi (Beefsteak)', 'Food', 'Đ. số 17/7 Kp. 38, P, Linh Xuân, Hồ Chí Minh, Việt Nam', 10.85986608203297, 106.78857552168786, 33000, 67000, 'Quán bò né chảo gang thơm phức với miếng bò mềm, trứng ốp la và pate béo ngậy. Lựa chọn tuyệt vời cho bữa sáng nhiều năng lượng hoặc bữa trưa nhanh gọn. Món dọn kèm bánh mì nóng giòn và đĩa salad dầu giấm chua ngọt vừa miệng.', ARRAY['Ẩm thực']),
  ('METROO COFFEE', 'Cafe', '513 Song Hành Xa Lộ Hà Nội, Linh Xuân, Hồ Chí Minh 70000, Việt Nam', 10.859138707600874, 106.78852741026576, 22000, 50000, 'Quán cà phê máy lạnh phong cách tối giản với view ngắm tuyến tàu điện metro. Thích hợp cho các bạn sinh viên ngồi học bài, chạy đồ án hoặc gặp gỡ đối tác. Quán có ổ cắm điện đầy đủ cùng wifi tốc độ cao, phục vụ nước uống cả ngày.', ARRAY['Cà phê']),
  ('Next Step Coffee', 'Cafe', '501 Song Hành Xa Lộ Hà Nội, Linh Xuân, Hồ Chí Minh, Việt Nam', 10.858919415373137, 106.788147365262, 17000, 49000, 'Quán cà phê trẻ trung hiện đại phục vụ các dòng cà phê máy và trà thanh mát. Phù hợp làm trạm dừng nạp năng lượng nhanh cho sinh viên và dân công sở. Đồ uống giá hạt dẻ, không gian sạch sẽ thoáng mát rất tiện ghé mua mang đi.', ARRAY['Cà phê']),
  ('Tiệm bánh nhà Vi', 'Food', '18/113 tổ 8, khu phố 6, Linh Xuân, Hồ Chí Minh, Việt Nam', 10.866951724251285, 106.79919305364407, 25000, 100000, 'Tiệm bánh ngọt nhỏ xinh quen thuộc của sinh viên Làng Đại học với đa dạng món bánh. Phù hợp cho những buổi hẹn hò ăn vặt nhẹ nhàng hoặc mua bánh kem tặng bạn bè. Bánh bông lan trứng muối và trà sữa ở tiệm có giá rất mềm, vị vừa miệng.', ARRAY['Ẩm thực', 'Chill nhẹ']),
  ('Cơm Gà Xối Mỡ Nghĩa Ký', 'Food', 'VQCX+J67, Đường Trục Chính 10, Linh Xuân, Hồ Chí Minh, Việt Nam', 10.871464794427508, 106.79809365475612, 25000, 40000, 'Quán cơm gà bình dân trứ danh với góc đùi gà xối mỡ giòn rụm và cơm rang đỏ. Điểm ăn trưa lý tưởng để nạp nhanh năng lượng cho sinh viên và du khách. Đĩa cơm đầy đặn kèm canh nóng hổi, giá cả rất vừa túi tiền mọi đối tượng.', ARRAY['Ẩm thực']),
  ('Cà Phê Chú Vũ', 'Cafe', '16/21 khu phố 33, Linh Xuân, Hồ Chí Minh, Việt Nam', 10.87165278155207, 106.7979163555655, 15000, 25000, 'Quán cà phê sân vườn mộc mạc đậm chất sinh viên khu Đại học Quốc gia. Không gian yên bình, thoáng đãng, thích hợp ngồi học bài hoặc chơi cờ thư giãn. Giá đồ uống bình dân, không khí sớm mai trong lành mang lại cảm giác dễ chịu.', ARRAY['Cà phê', 'Chill nhẹ']),
  ('Napoli Pizza', 'Food', '2a Hàn Thuyên, Thủ Đức, Hồ Chí Minh, Việt Nam', 10.846081342502101, 106.77063162109404, 59000, 189000, 'Quán pizza phong cách Ý với đế bánh nướng giòn thơm cùng phô mai béo ngậy. Lựa chọn tuyệt vời cho các buổi tiệc sinh nhật bạn bè hoặc bữa ăn gia đình. Mức giá khá mềm, món mỳ Ý xốt bò bằm và pizza thập cẩm rất được ưa chuộng.', ARRAY['Ẩm thực']),
  ('Công viên văn hóa Suối Tiên', 'CheckIn', '120 Song Hành Xa Lộ Hà Nội, Tăng Nhơn Phú, Hồ Chí Minh 70000, Việt Nam', 10.866243733652013, 106.80346629742044, 80000, 150000, 'Công viên giải trí văn hóa lịch sử lâu đời với nhiều trò chơi dưới nước hấp dẫn. Thích hợp cho gia đình có trẻ nhỏ và nhóm bạn trẻ vui chơi trọn ngày. Bạn nên chuẩn bị nón dù che nắng và đồ bơi để trải nghiệm biển Tiên Đồng.', ARRAY['Check-in', 'Văn hóa']),
  ('Metro Coffee - Suối Tiên', 'Cafe', '1 Số 13, Đông Hòa, Hồ Chí Minh, Việt Nam', 10.878845825654349, 106.81397324529563, 20000, 45000, 'Quán cà phê trạm dừng chân hiện đại với tầm nhìn hướng thẳng tuyến metro trên cao. Không gian thoải mái, tiện nạp năng lượng và chờ đón chuyến tàu tiếp theo. Đồ uống có mức giá bình dân, sáng sớm ghé mua ly cà phê mang đi rất tiện.', ARRAY['Cà phê']),
  ('Là gốm', 'CheckIn', '02 Nguyễn Bỉnh Khiêm, Thủ Đức, Hồ Chí Minh, Việt Nam', 10.846755103897761, 106.77107275347244, 100000, 250000, 'Xưởng gốm thủ công mộc mạc yên bình, nơi tự tay nhào nặn đồ gốm xinh xắn. Trải nghiệm thư giãn tâm trí mới lạ dành cho các cặp đôi hoặc nhóm bạn sáng tạo. Có thợ hướng dẫn tận tình từng bước, bạn sẽ được mang thành phẩm nung về nhà.', ARRAY['Check-in', 'Chill nhẹ']),
  ('THE TERMINAL Nhà hàng món Âu', 'Food', '3 Nguyễn Công Trứ, Thủ Đức, Hồ Chí Minh 71306, Việt Nam', 10.847216069242174, 106.77119375669112, 65000, 380000, 'Nhà hàng món Âu phong cách hiện đại với món bít tết hảo hạng và mỳ Ý chuẩn vị. Không gian tinh tế, lãng mạn, rất thích hợp cho các buổi hẹn hò hoặc kỷ niệm. Quán phục vụ chu đáo, bạn có thể gọi thêm ly rượu vang nhẹ để tối thêm trọn vẹn.', ARRAY['Ẩm thực']),
  ('Xoài Thái Kitchen', 'Food', '6/3, Đ. Số 3, Thủ Đức, Hồ Chí Minh, Việt Nam', 10.83521507761982, 106.76472458267217, 30000, 180000, 'Quán ẩm thực Thái Lan chuẩn vị với các món gỏi đu đủ và lẩu tomyum chua cay. Điểm hẹn ăn uống hấp dẫn cho nhóm bạn trẻ yêu thích các món ăn Chùa Vàng. Không gian quán gần gũi, các món xóc xốt thái đậm vị rất hợp nhâm nhi.', ARRAY['Ẩm thực']),
  ('Chạm Rooftop', 'Cafe', '99 Trần Thị Điệu, Phước Long, Hồ Chí Minh, Việt Nam', 10.831226516264534, 106.76983676757555, 39000, 129000, 'Quán bia rooftop lộng gió trên tầng thượng với góc ngắm hoàng hôn cực chill. Lựa chọn tuyệt vời cho các buổi hẹn hò lãng mạn hoặc tụ tập bạn bè cuối tuần. Bạn nên ghé quán từ 17h30 chiều để bắt trọn khoảnh khắc ráng chiều buông.', ARRAY['Cà phê', 'Chill nhẹ', 'Chụp ảnh']),
  ('Homes sushi', 'Food', '86e Trần Thị Điệu, Phước Long, Hồ Chí Minh, Việt Nam', 10.832170223578967, 106.76980970202517, 25000, 250000, 'Quán ẩm thực Nhật Bản bình dân nổi tiếng với sushi tươi ngon và lát cá béo ngậy. Rất hợp cho các bạn sinh viên hoặc gia đình muốn đổi vị ngon miệng. Quán có không gian ấm cúng, nên đặt bàn trước vào buổi tối để tránh chờ lâu.', ARRAY['Ẩm thực']),
  ('The Vibes Events & Dining', 'Food', '51bis An Phú, An Khánh, Hồ Chí Minh, Việt Nam', 10.808733433330975, 106.75087201859593, 85000, 550000, 'Tổ hợp nhà hàng sân vườn xanh mát kết hợp không gian ẩm thực sang trọng. Điểm hẹn đẳng cấp cho tiệc gia đình, gặp gỡ đối tác hoặc tổ chức sinh nhật. Thực đơn kết hợp Á - Âu tinh tế, cảnh quan về đêm lên đèn lung linh rất đẹp.', ARRAY['Ẩm thực']),
  ('Huyền coffee&Tea', 'Cafe', '2 Đường 2, KP1, An Khánh, Hồ Chí Minh 12345, Việt Nam', 10.808137824714473, 106.75486517253128, 18000, 40000, 'Quán nước sân vườn mộc mạc thoáng mát với menu trà trái cây và cà phê đậm đà. Điểm dừng chân chuyện trò thân mật cùng bạn bè hoặc ngồi thư giãn hóng gió. Mức giá đồ uống rất bình dân, cô chủ quán thân thiện và phục vụ nhanh nhẹn.', ARRAY['Cà phê', 'Chill nhẹ']),
  ('Rach Chiec Bridge Park', 'CheckIn', 'RQ74+384, An Khánh, Hồ Chí Minh, Việt Nam', 10.812702828157304, 106.7559080930727, 0, 0, 'Khuôn viên công viên ven sông thoáng đãng với góc ngắm toàn cảnh cầu Rạch Chiếc. Nơi lý tưởng để dạo bộ tập thể dục buổi chiều, hóng mát và chụp ảnh đón gió. Buổi tối không khí ven sông lộng gió, thích hợp ngồi ghế đá thư giãn sau giờ làm.', ARRAY['Thiên nhiên', 'Chill nhẹ', 'Chụp ảnh']),
  ('MM Mega Market An Phú', 'Food', 'Khu B, Khu đô thị An Phú An Khánh, Bình Trưng, Hồ Chí Minh 700000, Việt Nam', 10.800272756329004, 106.74329857250193, 0, 0, 'Đại siêu thị sỉ lẻ sầm uất với bạt ngàn thực phẩm tươi sống và quầy ăn uống. Phù hợp cho gia đình mua sắm cuối tuần hoặc nhóm bạn ghé mua đồ picnic. Siêu thị rất rộng, bạn nên mang theo áo khoác nhẹ khi vào khu đông lạnh.', ARRAY['Ẩm thực']),
  ('Á CHÂU DIMSUM HOUSE', 'Food', '90-92 Đường Số 15, Khu đô thị An Phú An Khánh, Thủ Đức, Hồ Chí Minh 70000, Việt Nam', 10.797761457196037, 106.74160124956471, 35000, 220000, 'Nhà hàng điểm tâm Quảng Đông chuẩn vị với menu há cảo và bánh bao nóng hổi. Thích hợp cho bữa sáng sum họp gia đình hoặc buổi tụ họp ẩm thực ấm cúng. Món chân gà tàu xì và xíu mại trứng muối ở đây rất đậm đà, đáng để thử.', ARRAY['Ẩm thực']),
  ('Công viên Vinhomes Central Park', 'CheckIn', 'Trần Trọng Kim, Vinhomes Tân Cảng, Thạnh Mỹ Tây, Hồ Chí Minh, Việt Nam', 10.793451928563789, 106.7246347403174, 0, 0, 'Đại công viên ven sông rộng lớn với bãi cỏ xanh mướt và khu vườn Nhật cầu đỏ. Điểm picnic, chụp hình check-in và dạo bộ ngoài trời tuyệt vời cho mọi lứa tuổi. Nên ghé vào tầm hoàng hôn đến tối để ngắm tháp Landmark 81 rực rỡ ánh đèn.', ARRAY['Check-in', 'Thiên nhiên', 'Chill nhẹ', 'Chụp ảnh']),
  ('Tháp quan sát Vinhomes Central Park', 'CheckIn', 'QPVG+65J, Vinhomes Tân Cảng, Thạnh Mỹ Tây, Hồ Chí Minh, Việt Nam', 10.793539660159265, 106.7256618242788, 0, 0, 'Đài quan sát trên cao độc đáo mang lại tầm nhìn toàn cảnh 360 độ về thành phố. Trải nghiệm khó quên cho du khách chiêm ngưỡng Sài Gòn phồn hoa từ trời cao. Bạn nên lên đài quan sát vào lúc chập tối để ngắm biển đèn lung linh tuyệt đẹp.', ARRAY['Check-in', 'Chụp ảnh']),
  ('Vincom Plaza Thủ Đức', 'CheckIn', '216 Đ. Võ Văn Ngân, Thủ Đức, Hồ Chí Minh 70000, Việt Nam', 10.85031023023696, 106.76544808803223, 0, 0, 'Trung tâm thương mại sôi động bậc nhất khu Đông tích hợp rạp chiếu phim và mua sắm. Điểm vui chơi, giải trí và tránh nóng quen thuộc cho giới trẻ cùng gia đình nhỏ. Các tầng tập trung nhiều thương hiệu ẩm thực, cà phê nổi tiếng tha hồ khám phá.', ARRAY['Check-in', 'Ẩm thực']),
  ('Vincom Plaza Lê Văn Việt', 'CheckIn', '50 Đ. Lê Văn Việt, Tăng Nhơn Phú, Hồ Chí Minh 71206, Việt Nam', 10.845101547251852, 106.77860706932226, 0, 0, 'Trung tâm mua sắm và giải trí tiện nghi trên trục đường sầm uất tại Thủ Đức. Nơi tụ họp ăn uống, xem phim cuối tuần lý tưởng cho cư dân và sinh viên lân cận. Khu ẩm thực phong phú với nhiều chuỗi lẩu nướng, gà rán quen thuộc tha hồ chọn.', ARRAY['Check-in', 'Ẩm thực']),
  ('Khu du lịch Văn Thánh', 'Food', '48/10 Điện Biên Phủ, Thạnh Mỹ Tây, Hồ Chí Minh, Việt Nam', 10.79892211171678, 106.71735502110549, 50000, 300000, 'Ốc đảo xanh yên ả giữa lòng phố thị với hồ sen, rặng tre và bãi cỏ xanh mướt. Điểm hẹn nghỉ dưỡng cuối tuần lý tưởng để cắm trại picnic hoặc ăn món quê. Cuối tuần ở đây thường có tiệc buffet ẩm thực ba miền rất phong phú và ngon miệng.', ARRAY['Ẩm thực', 'Thiên nhiên', 'Chill nhẹ']),
  ('Pearl Plaza', 'CheckIn', '561A Điện Biên Phủ, Thạnh Mỹ Tây, Hồ Chí Minh 700000, Việt Nam', 10.800127315652643, 106.71896417512919, 0, 0, 'Khu phức hợp thương mại hiện đại tích hợp siêu thị, phòng gym và rạp chiếu phim. Điểm đến thuận tiện để mua sắm, xem phim giải trí và ăn uống đa dạng món ngon. Nằm sát trạm metro Văn Thánh, rất tiện dừng chân dạo chơi giữa lịch trình.', ARRAY['Check-in', 'Ẩm thực']);
